var source = outputs.collect_news || {};
var items = Array.isArray(source.items) ? source.items : [];
var catalog = {};
var lines = [];
var fallback = "<b>Điểm tin Việt Nam buổi sáng</b>\n";
function esc(value) {
  return String(value == null ? "" : value)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
var limit = Math.min(items.length, 30);
for (var i = 0; i < limit; i++) {
  var item = items[i] || {};
  var id = "N" + (i + 1);
  catalog[id] = item;
  lines.push(
    id + " | " + String(item.publisher || "") + " | " +
    String(item.published_at || "") + " | " + String(item.title || "") +
    " | " + String(item.summary || "")
  );
}
if (items.length === 0) {
  fallback += "\nKhông tìm thấy tin mới có thời gian xuất bản hợp lệ trong 24 giờ qua.";
} else {
  var fallbackLimit = Math.min(items.length, 10);
  for (var j = 0; j < fallbackLimit; j++) {
    var entry = items[j] || {};
    fallback += "\n\n<b>" + (j + 1) + ". " + esc(entry.title || "Tin mới") + "</b>";
    if (entry.summary) fallback += "\n" + esc(String(entry.summary).slice(0, 220));
    fallback += "\nNguồn: <a href=\"" + esc(entry.url || "") + "\">" + esc(entry.publisher || "Nguồn gốc") + "</a>";
  }
}
if (Array.isArray(source.source_errors) && source.source_errors.length > 0) {
  fallback += "\n\n<i>Một số nguồn tạm thời không đọc được; bản tin vẫn được tạo từ các nguồn còn lại.</i>";
}
if (fallback.length > 3900) fallback = fallback.slice(0, 3860) + "…";
var prompt = "";
if (lines.length > 0) {
  prompt =
    "Từ danh sách ứng viên tin tức dưới đây, chọn tối đa 10 câu chuyện đáng chú ý cho độc giả Việt Nam trong bản tin buổi sáng. " +
    "Chỉ dùng thông tin có trong dữ liệu được cung cấp; không bổ sung sự kiện, số liệu, nguyên nhân hoặc nguồn khác. " +
    "Gộp các mục nếu chúng rõ ràng nói về cùng một sự kiện. Trả về JSON thuần, không markdown, đúng dạng " +
    "{\"stories\":[{\"headline\":\"...\",\"summary\":\"1-2 câu ngắn\",\"ids\":[\"N1\"]}]}. " +
    "Mỗi story phải có ít nhất một id hợp lệ từ danh sách. Không đưa URL vào JSON. Nếu dữ liệu không đủ chắc chắn thì bỏ mục đó.\n\n" +
    lines.join("\n");
}
return {
  prompt: prompt,
  fallback_message: fallback,
  catalog: catalog,
  candidate_count: items.length,
  sources_ok: source.sources_ok || 0
};

var prepared = outputs.prepare_brief || {};
var fallback = String(prepared.fallback_message || "<b>Điểm tin Việt Nam buổi sáng</b>\nKhông có dữ liệu.");
var catalog = prepared.catalog || {};
var raw = String((outputs.openai_summary || {}).ai_response || "").trim();
function esc(value) {
  return String(value == null ? "" : value)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
try {
  raw = raw.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "");
  var parsed = JSON.parse(raw);
  var stories = Array.isArray(parsed.stories) ? parsed.stories : [];
  var message = "<b>Điểm tin Việt Nam buổi sáng</b>\n";
  var used = 0;
  for (var i = 0; i < stories.length && used < 10; i++) {
    var story = stories[i] || {};
    var ids = Array.isArray(story.ids) ? story.ids : [];
    var sources = [];
    var sourceSeen = {};
    for (var j = 0; j < ids.length; j++) {
      var id = String(ids[j] || "");
      var item = catalog[id];
      if (!item || !item.url || sourceSeen[item.url]) continue;
      sourceSeen[item.url] = true;
      sources.push(item);
    }
    if (sources.length === 0) continue;
    var headline = String(story.headline || sources[0].title || "Tin đáng chú ý").trim();
    var summary = String(story.summary || "").trim();
    if (!summary) continue;
    var block = "\n\n<b>" + (used + 1) + ". " + esc(headline.slice(0, 180)) + "</b>\n" +
      esc(summary.slice(0, 420)) + "\nNguồn: ";
    var links = [];
    for (var k = 0; k < sources.length && k < 3; k++) {
      links.push("<a href=\"" + esc(sources[k].url) + "\">" + esc(sources[k].publisher || "Nguồn " + (k + 1)) + "</a>");
    }
    block += links.join(" · " );
    if (message.length + block.length > 3850) break;
    message += block;
    used++;
  }
  if (used === 0) return {message: fallback, used_ai: false, story_count: 0};
  var source = outputs.collect_news || {};
  if (Array.isArray(source.source_errors) && source.source_errors.length > 0 && message.length < 3750) {
    message += "\n\n<i>Một số nguồn tạm thời không đọc được; bản tin dùng các nguồn còn lại.</i>";
  }
  return {message: message, used_ai: true, story_count: used};
} catch (err) {
  return {message: fallback, used_ai: false, story_count: 0};
}

